def second_largest(xs):
    if len(xs) < 2:
        return None
    unique_xs = []
    seen = set()
    for x in xs:
        if x not in seen:
            unique_xs.append(x)
            seen.add(x)
    if len(unique_xs) < 2:
        return None
    return unique_xs[-2]

