        return ""
    result = []
    count = 1
    prev_char = s[0]
    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            result.append(f"{count}{prev_char}")
            prev_char = char
            count = 1
    result.append(f"{count}{prev_char}")
    return "".join(result)

def rle(s):
    result = []
    i = 0
    while i < len(s):
        count = 1
        while i + count < len(s) and s[i] == s[i + count]:
