def index_of(xs, x):
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid
        else:
            hi = mid
    return lo

def flatten(xs):
    result = []
    def recurse(lst):
        for item in lst:
            if isinstance(item, list):
                recurse(item)
            else:
                result.append(item)
    recurse(xs)
    return result

def to_roman(n):
    vals = [(1000, 'M'), (500, 'D'), (100, 'C'), (50, 'L'), (10, 'X'), (5, 'V'), (1, 'I')]
    out = ''
    for v, s in vals:
        while n >= v:
            out += s
            n -= v
    return out

